const state = {
  apiKey: localStorage.getItem('yanqi_api_key') || '',
  cardType: 'capabilities',
};

function api(path, opts = {}) {
  const headers = Object.assign({ 'Content-Type': 'application/json' }, opts.headers || {});
  if (state.apiKey) headers['X-API-Key'] = state.apiKey;
  // M56：剥离 UI 选项，避免传入 fetch
  const {
    busy: _busy,
    busyText: _bt,
    quiet: _q,
    successToast: _st,
    noRedirectOn401: _nr,
    noBust: _nb,
    ...fetchOpts
  } = opts;
  const token = localStorage.getItem('yanqi_token');
  if (token && !headers.Authorization) headers.Authorization = 'Bearer ' + token;
  return fetch('/api' + path, { ...fetchOpts, headers, credentials: 'include' }).then(async (r) => {
    if (!r.ok) {
      let msg = '';
      try {
        const ct = r.headers.get('content-type') || '';
        if (ct.includes('application/json')) {
          const j = await r.json();
          msg = j.messageZh || j.message || j.error || JSON.stringify(j);
        } else {
          msg = await r.text();
        }
      } catch (_) {
        msg = r.statusText || '';
      }
      if (r.status === 401) throw new Error(msg || '登录已失效（401），请重新登录');
      if (r.status === 403) throw new Error(msg || '没有权限（403）');
      throw new Error(msg || r.statusText || String(r.status));
    }
    const ct = r.headers.get('content-type') || '';
    if (ct.includes('application/json')) return r.json();
    return r.text();
  });
}

function showDlg(text) {
  dlgBody.textContent = text;
  dlg.showModal();
}

function statusLabel(s) {
  return (
    {
      PENDING_REVIEW: '待复核',
      APPROVED: '已通过',
      REJECTED: '已驳回',
      CONTACTED: '已触达',
      CLOSED: '已关闭',
    }[s] || s
  );
}

