btnLogin.onclick = async () => {
  const res = await api('/auth/login', {
    method: 'POST',
    body: JSON.stringify({ username: user.value, password: pass.value }),
  });
  if (res.ok) {
    if (res.token) localStorage.setItem('yanqi_token', res.token);
    if (res.apiKey) {
      state.apiKey = res.apiKey;
      localStorage.setItem('yanqi_api_key', state.apiKey);
    } else {
      localStorage.removeItem('yanqi_api_key');
    }
    const home = res.homePath || res.user?.homePath;
    if (home && !String(home).includes('ops.html') && home !== '/ops.html') {
      location.href = home;
      return;
    }
    authState.textContent = (res.personaLabel || '运营') + ' · 已登录';
    refreshTab('dash');
  } else {
    authState.textContent = res.message || '失败';
  }
};

if (state.apiKey) authState.textContent = '已带密钥';

/** M46–M48：优先一次性 sse_ticket（path + 可选 jobId）；失败再拼 access_token */
async function sseUrl(path) {
  try {
    let streamPath = String(path || '').split('?')[0];
    let jobId = null;
    const qs = String(path).includes('?') ? String(path).split('?')[1] : '';
    try {
      const sp = new URLSearchParams(qs);
      jobId = sp.get('id') || sp.get('jobId');
    } catch (_) {}
    if (streamPath && !streamPath.startsWith('/')) streamPath = '/' + streamPath;
    if (streamPath.startsWith('/jobs/') || streamPath.startsWith('/imports/')) streamPath = '/api' + streamPath;
    if (!jobId) {
      const m = /\/jobs\/([^/]+)\/progress/.exec(streamPath);
      if (m && m[1] !== 'progress') jobId = m[1];
    }
    const body = { purpose: 'sse-progress', streamPath: streamPath };
    if (jobId) body.jobId = jobId;
    const r = await api('/jobs/sse-ticket', {
      method: 'POST',
      body: JSON.stringify(body),
    });
    if (r && r.ticket) {
      const join = String(path).includes('?') ? '&' : '?';
      return path + join + 'sse_ticket=' + encodeURIComponent(r.ticket);
    }
  } catch (_) {}
  try {
    const tok = localStorage.getItem('yanqi_token') || '';
    if (!tok) return path;
    const join = String(path).includes('?') ? '&' : '?';
    return path + join + 'access_token=' + encodeURIComponent(tok);
  } catch (_) {
    return path;
  }
}

async function refreshResumeTaskCards() {
  const el = document.getElementById('resumeTaskCards');
  if (!el) return;
  if (window.YB && typeof YB.loadResumeCards === 'function') {
    await YB.loadResumeCards(el, {
      limit: 12,
      onChanged: () => {
        refreshResumeTaskCards().catch(() => {});
        refreshJobs().catch(() => {});
        refreshImports().catch(() => {});
      },
      onResume: async ({ kind, path, body }) => {
        const r = await api(path, { method: 'POST', body: JSON.stringify(body || {}) });
        if (!r.ok && r.messageZh) {
          showDlg(r.messageZh);
          throw new Error(r.messageZh);
        }
        showDlg(r.summaryZh || '已续跑入队');
        if (kind === 'match' && (r.jobId || r.id)) {
          window.__yanqiLastMatchJobId = r.jobId || r.id;
          const box = document.getElementById('jobProgressBox');
          if (box) box.style.display = 'block';
          pollJobProgress(r.jobId || r.id).catch(() => {});
        }
        if (kind === 'import') {
          window.__yanqiImportJobId = r.jobId || (body && body.id);
          const box = document.getElementById('importProgressBox');
          if (box) box.style.display = 'block';
          if (r.jobId) pollImportProgress(r.jobId).catch(() => {});
        }
      },
    });
    return;
  }
  // fallback without YB
  try {
    const data = await api('/jobs/resume-cards?limit=12');
    const cards = data.cards || [];
    el.innerHTML = cards.length
      ? cards
          .map(
            (c) =>
              `<div class="item resume-card"><strong>${c.titleZh || c.kindZh}</strong> · ${c.statusZh || ''} · ${c.summaryZh || ''}</div>`,
          )
          .join('')
      : `<div class="item resume-card empty-calm"><p class="muted" style="margin:0">${data.emptyZh || '暂无续跑任务'}</p></div>`;
  } catch (e) {
    el.innerHTML = `<p class="muted">续跑卡加载失败</p>`;
  }
}

async function refreshDash() {
  const s = await api('/stats');
  statsCards.innerHTML = [
    ['组织', s.orgs],
    ['能力卡', s.caps],
    ['成果卡', s.outs],
    ['需求卡', s.demands],
    ['匹配', s.matches],
    ['线索', s.leads],
    ['联系人', s.people],
  ]
    .map(([l, n]) => `<div class="stat"><div class="n">${n}</div><div class="l">${l}</div></div>`)
    .join('');
  topMatches.innerHTML =
    (s.topMatches || [])
      .map((m) => {
        const supply = m.capability?.title || m.outcome?.title || '-';
        return `<div class="item"><h4><span class="score">${(m.totalScore * 100).toFixed(0)}分</span> · ${m.demand?.title || ''}</h4>
        <div class="meta">供给：${supply} · ${statusLabel(m.status)}</div>
        <div class="reason">${m.reason || ''}</div></div>`;
      })
      .join('') || '<div class="muted">暂无匹配，点上面「跑一轮匹配」</div>';
  refreshResumeTaskCards().catch(() => {});
}

