async function refreshMatches() {
  const min = Number(document.getElementById('filterScore')?.value || 0);
  const st = document.getElementById('filterStatus')?.value || '';
  const qs = new URLSearchParams();
  if (min > 0) qs.set('minScore', String(min));
  if (st) qs.set('status', st);
  const q = qs.toString() ? '?' + qs.toString() : '';
  const rows = await api('/matches' + q);
  matchList.innerHTML =
    rows
      .map((m) => {
        const supply = m.capability?.title || m.outcome?.title || '-';
        const supplyOrg = m.capability?.org?.name || m.outcome?.org?.name || '';
        return `<div class="item">
        <h4><span class="score">${(m.totalScore * 100).toFixed(0)}分</span> ${m.demand?.title || ''}</h4>
        <div class="meta">需求方：${m.demand?.org?.name || ''} → 供给：${supply}（${supplyOrg}） · ${statusLabel(m.status)}</div>
        <div class="reason">${m.reason || ''}</div>
        <div class="row">
          <button data-approve="${m.id}">通过</button>
          <button class="ghost" data-reject="${m.id}">驳回</button>
          <button class="ghost" data-regen="${m.id}">重写草稿</button>
          <button class="ghost" data-close="${m.id}">关闭</button>
          <button class="ghost" data-fb-yes="${m.id}">有用</button>
          <button class="ghost" data-fb-no="${m.id}">不准</button>
          <button class="ghost" data-assign="${m.id}">分派经纪人</button>
        </div>
        <div class="meta">${m.broker ? '经纪人：' + m.broker.name : '未分派经纪人'}</div>
      </div>`;
      })
      .join('') || '<div class="muted">暂无</div>';

  matchList.querySelectorAll('[data-approve]').forEach((b) => {
    b.onclick = async () => {
      await api('/matches/' + b.dataset.approve, { method: 'PATCH', body: JSON.stringify({ status: 'APPROVED' }) });
      refreshMatches();
    };
  });
  matchList.querySelectorAll('[data-reject]').forEach((b) => {
    b.onclick = async () => {
      await api('/matches/' + b.dataset.reject, {
        method: 'PATCH',
        body: JSON.stringify({ status: 'REJECTED', operatorNote: '运营驳回' }),
      });
      refreshMatches();
    };
  });
  matchList.querySelectorAll('[data-regen]').forEach((b) => {
    b.onclick = async () => {
      const lead = await api('/matches/' + b.dataset.regen + '/regenerate-draft', { method: 'POST', body: '{}' });
      showDlg(`已重写草稿\n主题：${lead.draftSubject}\n\n${lead.draftBody}`);
      refreshLeads();
    };
  });
  matchList.querySelectorAll('[data-close]').forEach((b) => {
    b.onclick = async () => {
      await api('/matches/' + b.dataset.close, { method: 'PATCH', body: JSON.stringify({ status: 'CLOSED' }) });
      refreshMatches();
    };
  });
  matchList.querySelectorAll('[data-fb-yes]').forEach((b) => {
    b.onclick = async () => {
      await api('/feedback/matches/' + b.dataset.fbYes, { method: 'POST', body: JSON.stringify({ useful: true }) });
      showDlg('已记「有用」并微调权重');
    };
  });
  matchList.querySelectorAll('[data-fb-no]').forEach((b) => {
    b.onclick = async () => {
      await api('/feedback/matches/' + b.dataset.fbNo, { method: 'POST', body: JSON.stringify({ useful: false }) });
      showDlg('已记「不准」并微调权重');
    };
  });
  matchList.querySelectorAll('[data-assign]').forEach((b) => {
    b.onclick = async () => {
      const brokers = await api('/brokers');
      if (!brokers.length) { showDlg('还没有经纪人账号，请先用 broker@yanqi.local 登录或种子初始化'); return; }
      const brokerId = brokers[0].id;
      try {
        const row = await api('/brokers/assign', { method: 'POST', body: JSON.stringify({ matchId: b.dataset.assign, brokerId }) });
        showDlg('已分派给 ' + (row.broker?.name || brokers[0].name));
        refreshMatches();
        if (typeof refreshBrokers === 'function') refreshBrokers();
      } catch (err) {
        showDlg(err.message || '这条现在不能分派');
      }
    };
  });
}

async function refreshLeads() {
  const rows = await api('/leads');
  leadList.innerHTML =
    rows
      .map((l) => {
        return `<div class="item">
        <h4>${l.draftSubject || '（无主题）'}</h4>
        <div class="meta">状态 ${l.status}${l.sendMode ? ' · ' + l.sendMode : ''} · 渠道 ${l.channel} · 联系人 ${l.person?.name || '待补'} ${l.person?.email || ''}</div>
        <div class="reason">${(l.draftBody || '').slice(0, 220)}...</div>
        <div class="row">
          <button class="ghost" data-view="${l.id}">看全文草稿</button>
          ${(l.match?.scoreBreakdown?.action === 'SHADOW' || l.match?.scoreBreakdown?.action === 'HOLD')
            ? '<span class="pill">内部观察，先不发</span>'
            : (['draft','failed','dry_run'].includes(l.status) ? `<button data-approve-send="${l.id}">审核通过并入队发送</button>` : '')}
          ${l.matchId && !['approved','sent','dry_run'].includes(l.status) ? `<button class="ghost" data-regen-lead="${l.matchId}">按匹配重写</button>` : ''}
        </div>
      </div>`;
      })
      .join('') || '<div class="muted">暂无线索</div>';
  leadList.querySelectorAll('[data-view]').forEach((b) => {
    b.onclick = async () => {
      const l = await api('/leads/' + b.dataset.view);
      showDlg(`主题：${l.draftSubject}\n\n${l.draftBody}`);
    };
  });
  leadList.querySelectorAll('[data-approve-send]').forEach((b) => {
    b.onclick = async () => {
      if (!confirm('确认审核通过并入队发送？未配 SMTP 时只干跑写日志，不会真发。')) return;
      const res = await api('/leads/' + b.dataset.approveSend + '/approve-send', {
        method: 'POST',
        body: JSON.stringify({ actor: 'ops' }),
      });
      showDlg((res.message || '') + '\n模式：' + (res.mode || '') + '\n状态：' + (res.lead?.status || ''));
      refreshLeads();
      refreshMatches();
      refreshDash();
    };
  });
  leadList.querySelectorAll('[data-regen-lead]').forEach((b) => {
    b.onclick = async () => {
      try {
        const lead = await api('/matches/' + b.dataset.regenLead + '/regenerate-draft', { method: 'POST', body: '{}' });
        if (lead && lead.ok === false) {
          showDlg(lead.message || '先不重写');
          return;
        }
        showDlg(`已重写草稿\n主题：${lead.draftSubject}\n\n${lead.draftBody}`);
        refreshLeads();
      } catch (err) {
        showDlg(err.message || '这条草稿不能重写');
      }
    };
  });
}

