function refreshTab(tab) {
  if (tab === 'dash') return refreshDash().catch(showErr);
  if (tab === 'orgs') return refreshOrgs().catch(showErr);
  if (tab === 'cards') return refreshCards().catch(showErr);
  if (tab === 'match') return refreshMatches().catch(showErr);
  if (tab === 'leads') return refreshLeads().catch(showErr);
  if (tab === 'jobs') return refreshJobs().catch(showErr);
  if (tab === 'audits') return refreshAudits().catch(showErr);
  if (tab === 'brokers') return typeof refreshBrokers === 'function' ? refreshBrokers().catch(showErr) : null;
  if (tab === 'playbooks') return typeof refreshFunnel === 'function' ? refreshFunnel().catch(showErr) : null;
  if (tab === 'reviews') return typeof refreshReviews === 'function' ? refreshReviews().catch(showErr) : null;
  if (tab === 'taxonomy') return typeof refreshTaxonomy === 'function' ? refreshTaxonomy().catch(showErr) : null;
  if (tab === 'doctpl') return typeof refreshTemplates === 'function' ? refreshTemplates().catch(showErr) : null;
  if (tab === 'capacity') return typeof refreshCapacity === 'function' ? refreshCapacity().catch(showErr) : null;
  if (tab === 'cases') return typeof refreshCases === 'function' ? refreshCases().catch(showErr) : null;
  if (tab === 'flywheel') return typeof refreshFlywheel === 'function' ? refreshFlywheel().catch(showErr) : null;
  if (tab === 'quality') return typeof refreshQuality === 'function' ? refreshQuality().catch(showErr) : null;
}

function showErr(e) {
  console.error(e);
  authState.textContent = '请求失败：' + (e.message || e);
}

async function runMatch() {
  const minScoreVal = Number(document.getElementById('minScore')?.value || 0.25);
  const busyHost = document.getElementById('matchSkipOut') || document.getElementById('authState');
  if (typeof YB !== 'undefined' && YB.busy) YB.busy(true, '正在跑匹配（批写中）…');
  else if (busyHost) busyHost.textContent = '正在跑匹配，请稍候…';
  if (typeof toast === 'function') toast('匹配已开始，请勿重复连点', 'ok');
  try {
    const res = await api('/matches/run', { method: 'POST', body: JSON.stringify({ topN: 5, minScore: minScoreVal }) });
    const samples = [...(res.skippedDemandSamples || []), ...(res.skippedSupplySamples || [])];
    const skipTxt =
      (res.skipReasonsZh || '') +
      (samples.length
        ? '\n跳过样例：\n' + samples.map((s) => `- [${s.kind || 'demand'}] ${s.title} · ${s.reason}`).join('\n')
        : '');
    const skipBox = document.getElementById('matchSkipOut');
    if (skipBox) {
      skipBox.style.display = skipTxt.trim() ? 'block' : 'none';
      skipBox.textContent = skipTxt;
    }
    const banner = res.cancelled
      ? `已取消：生成 ${res.count} 条后停下`
      : `匹配完成：${res.count} 条（向量 ${res.embedding?.mode || 'hash'} · M56 批写）`;
    showDlg(
      banner +
        '\n' +
        (res.skipReasonsZh ? res.skipReasonsZh + '\n' : '') +
        (res.items || []).map((i) => `${i.score} | ${i.demand} ↔ ${i.supply}`).join('\n'),
    );
    if (typeof YB !== 'undefined' && YB.toast) YB.toast(banner, res.cancelled ? 'warn' : 'ok');
    else if (typeof toast === 'function') toast(banner, res.cancelled ? 'warn' : 'ok');
    refreshDash();
    refreshMatches();
    refreshLeads();
  } catch (e) {
    const msg = String(e.message || e || '');
    if (/401/.test(msg)) {
      if (typeof YB !== 'undefined' && YB.toast) YB.toast('登录已失效，无法跑匹配（401）', 'security');
      else toast('登录已失效，无法跑匹配（401）', 'err');
    } else if (/403/.test(msg)) {
      if (typeof YB !== 'undefined' && YB.toast) YB.toast('没有权限跑匹配（403）', 'security');
      else toast('没有权限跑匹配（403）', 'err');
    } else if (/MATCH_BUSY|正在跑/.test(msg)) {
      if (typeof YB !== 'undefined' && YB.toast) YB.toast('匹配正在跑，请稍候再试', 'warn');
      else toast('匹配正在跑，请稍候再试', 'warn');
    } else {
      throw e;
    }
  } finally {
    if (typeof YB !== 'undefined' && YB.busy) YB.busy(false);
  }
}

btnRunMatch.onclick = () => runMatch().catch(showErr);
btnRunMatch2.onclick = () => runMatch().catch(showErr);
