  timelineMeta.textContent =
    (m.demand?.title || matchId) +
    ' · 当前 ' +
    (FOLLOW_LABEL[m.followUpStatus] || m.followUpStatus || '未开始') +
    ' · 经纪人 ' +
    (m.broker?.name || '-');
  timelineEvents.innerHTML =
    (m.followUps || [])
