window.__yanqiConflictAsyncExportId = null;
function paintAsyncConflictProgress(r) {
  const box = document.getElementById('asyncConflictProgressBox');
  if (box) box.style.display = 'block';
  const pct = Math.max(0, Math.min(100, Number(r.percent) || 0));
  const fill = document.getElementById('asyncConflictFill');
  const pctEl = document.getElementById('asyncConflictPct');
  const phase = document.getElementById('asyncConflictPhase');
  const meta = document.getElementById('asyncConflictMeta');
  if (fill) fill.style.width = pct + '%';
  if (pctEl) pctEl.textContent = pct + '%';
  if (phase) phase.textContent = (r.phaseZh || r.status || '') + (r.format ? ' · ' + String(r.format).toUpperCase() : '');
  if (meta) meta.textContent = (r.bannerZh || r.messageZh || '') + (r.exportedRows != null ? ' · 行 ' + r.exportedRows + '/' + (r.totalRows || '?') : '');
  const cancelBtn = document.getElementById('btnCancelConflictAsync');
  const dlBtn = document.getElementById('btnDownloadConflictAsync');
  if (cancelBtn) cancelBtnEnable(cancelBtn, !!r.waiting);
  if (dlBtn) cancelBtnEnable(dlBtn, !r.waiting && r.status === 'done' && !!r.downloadPath);
}

async function pollAsyncConflictExport(importJobId, exportId) {
  window.__yanqiConflictAsyncExportId = exportId;
  for (let i = 0; i < 180; i++) {
    const r = await api(
      '/imports/enterprise/jobs/' +
        encodeURIComponent(importJobId) +
        '/conflict-export/jobs/' +
        encodeURIComponent(exportId),
    );
    paintAsyncConflictProgress(r);
    if (!r.waiting) {
      if (r.status === 'done') showDlg(r.bannerZh || '异步冲突导出完成，可下载');
      else if (r.status === 'cancelled') showDlg(r.bannerZh || '异步导出已取消');
      else if (r.status === 'failed') showDlg(r.bannerZh || r.errorZh || '异步导出失败');
      return r;
    }
    await new Promise((x) => setTimeout(x, 800));
  }
}

