async function refreshHomeCacheCurveDash() {
  const el = document.getElementById('homeCacheCurveDash');
  if (!el) return;
  try {
    const curve = await api('/metrics/home-cache/curve?limit=48');
    const alerts = await api('/metrics/home-cache/curve/alerts').catch(() => null);
    const labels = curve.labels || [];
    const series = curve.series || {};
    const shells = curve.shells || [];
    let text = '点数 ' + (curve.count || 0) + ' · 刷新间隔约 ' + Math.round((curve.flushMs || 0) / 1000) + 's\n';
    if (alerts && alerts.messageZh) {
      text += (alerts.alerting ? '⚠ ' : '✓ ') + alerts.messageZh + '\n';
    }
    if (!labels.length) {
      text += '尚无持久点。各壳打开首页后会自动落盘，或点「落盘当前点」。';
    } else {
      const last = labels.length - 1;
      text += '最新 ' + labels[last] + '\n';
      text += '合计命中率% ' + (series.totalHitRatePct && series.totalHitRatePct[last] != null ? series.totalHitRatePct[last] : '—') + '\n';
      for (const s of shells) {
        const arr = series[s] || [];
        const shellAlert = (alerts && alerts.shells || []).find((x) => x.shell === s);
        const mark = shellAlert && shellAlert.alerting ? ' ⚠' : '';
        text += '  ' + s + ': ' + (arr[last] == null ? '—' : arr[last] + '%') + mark + '\n';
      }
      text += '\n（完整序列见 GET /api/metrics/home-cache/curve；持续偏低告警见 /curve/alerts；双通道 POST .../alerts/notify）';
      if (alerts && alerts.dualChannel) {
        text += '\n双通道：' + (alerts.dualChannel.channel1Zh || '通道一') + ' · ' + (alerts.dualChannel.channel2Zh || '通道二');
      }
    }
    el.textContent = text;
  } catch (e) {
    el.textContent = '曲线加载失败：' + (e.message || e);
  }
}
