async function refreshExportQuotaBadge() {
  const badge = document.getElementById('exportQuotaBadge');
  const dash = document.getElementById('exportQuotaWarnDash');
  if (!badge) return;
  try {
    const data = await api('/imports/enterprise/conflict-export/async/quota-warnings');
    const level = data.worstLevel || 'ok';
    badge.textContent = data.badgeZh || '配额正常';
    badge.dataset.level = level;
    badge.classList.remove('warn', 'danger', 'ok');
    if (level === 'near') badge.classList.add('warn');
    else if (level === 'critical' || level === 'over') badge.classList.add('danger');
    else badge.classList.add('ok');
    if (dash) {
      const lines = [];
      lines.push((data.tipZh || '') + '');
      lines.push('全局 ' + Math.round((data.globalRatio || 0) * 1000) / 10 + '% · ' + (data.globalLevel || 'ok'));
      const list = data.warnings && data.warnings.length ? data.warnings : (data.tenants || []).slice(0, 5);
      for (const w of list) {
        lines.push((w.tenantId || '') + ' · ' + (w.badgeZh || w.level) + ' · ' + Math.round((w.bytes || 0) / 1024) + 'KB');
      }
      if (data.dualChannel) {
        lines.push('双通道：' + (data.dualChannel.channel1Zh || '通道一') + ' · ' + (data.dualChannel.channel2Zh || '通道二'));
        if (data.dualChannel.tipZh) lines.push(data.dualChannel.tipZh);
      }
      if (data.alertingCount || data.dualChannel) {
        dash.style.display = 'block';
        dash.textContent = lines.filter(Boolean).join('\n');
      } else {
        dash.style.display = 'none';
        dash.textContent = '';
      }
    }
  } catch (e) {
    badge.textContent = '配额检测失败';
    badge.dataset.level = 'unknown';
  }
}
