async function pollSnapshotAuditAsyncExport(exportId) {
  const box = document.getElementById('snapshotAuditAsyncProgressBox');
  const banner = document.getElementById('snapshotAuditAsyncBanner');
  const hint = document.getElementById('snapshotAuditAsyncHint');
  const bar = document.getElementById('snapshotAuditAsyncBar');
  const dl = document.getElementById('snapshotAuditAsyncDownload');
  const cancelBtn = document.getElementById('btnCancelSnapshotAuditAsync');
  if (box) box.style.display = 'block';
  __yanqiAuditExportId = exportId;
  if (cancelBtn) cancelBtn.disabled = false;
  const tick = async () => {
    try {
      const p = await api('/jobs/research-snapshot-audits/export/jobs/' + exportId);
      if (banner) banner.textContent = (p.phaseZh || '') + ' · ' + (p.bannerZh || p.status || '');
      if (hint) hint.textContent = p.hintZh || '';
      if (bar) bar.value = Number(p.percent) || 0;
      if (p.downloadPath && dl) {
        dl.href = p.downloadPath;
        dl.style.display = 'inline-block';
      }
      if (!p.waiting) {
        if (cancelBtn) cancelBtn.disabled = true;
        if (__yanqiAuditExportPoll) {
          clearInterval(__yanqiAuditExportPoll);
          __yanqiAuditExportPoll = null;
        }
        if (p.status === 'done') showDlg('异步审计导出已就绪，可下载');
        else if (p.status === 'cancelled') showDlg('异步审计导出已取消');
        else if (p.status === 'failed') showDlg(p.bannerZh || '异步审计导出失败');
      }
    } catch (e) {
      if (banner) banner.textContent = '进度刷新失败：' + (e.message || e);
    }
  };
  await tick();
  if (__yanqiAuditExportPoll) clearInterval(__yanqiAuditExportPoll);
  __yanqiAuditExportPoll = setInterval(tick, 900);
}
