async function loadOpsDocMeta() {
  try {
    const t = await api('/park/doc-templates');
    const sel = document.getElementById('opsDocTpl');
    if (sel) {
      const cur = sel.value;
      sel.innerHTML =
        '<option value="">模板（文号规则）</option>' +
        (t.templates || [])
          .map(
            (x) =>
              `<option value="${x.id}" data-dir="${x.direction || ''}" data-title="${(x.titleHintZh || '').replace(/"/g, '&quot;')}" data-body="${(x.bodyHintZh || '').replace(/"/g, '&quot;')}" data-ex="${x.exampleDocNo || ''}">${x.nameZh} · ${x.docNoRule}</option>`,
          )
          .join('');
      if (cur) sel.value = cur;
    }
    const board = await api('/park/board');
    const w = document.getElementById('opsDocWin');
    if (w) {
      const cur = w.value;
      w.innerHTML =
        '<option value="">关联征集窗</option>' +
        (board.windows || []).map((x) => `<option value="${x.id}">${x.titleZh}（${x.statusZh || x.status}）</option>`).join('');
      if (cur) w.value = cur;
    }
  } catch (_) {}
}
document.getElementById('opsDocTpl') &&
  (document.getElementById('opsDocTpl').onchange = () => {
    const sel = document.getElementById('opsDocTpl');
    const opt = sel.selectedOptions[0];
    const hint = document.getElementById('opsDocTplHint');
    if (!opt || !opt.value) {
      if (hint) hint.textContent = '';
      return;
    }
    if (opt.dataset.dir) document.getElementById('opsDocDir').value = opt.dataset.dir;
    const titleEl = document.getElementById('opsDocTitle');
    const bodyEl = document.getElementById('opsDocBody');
    if (opt.dataset.title && titleEl && !titleEl.value.trim()) titleEl.value = opt.dataset.title;
    if (opt.dataset.body && bodyEl && !bodyEl.value.trim()) bodyEl.value = opt.dataset.body;
    if (hint) hint.textContent = '预计文号示例：' + (opt.dataset.ex || '');
  });

async function refreshParkDocs() {
  await loadOpsDocMeta();
  const d = await api('/park/docs');
  const banner = document.getElementById('opsDocsBanner');
  if (banner && d.bannerZh) banner.textContent = d.bannerZh;
  const k = document.getElementById('opsDocsKpis');
  if (k && d.counts) {
    k.innerHTML = [
      ['全部', d.counts.total],
      ['草稿', d.counts.draft],
      ['已发出', d.counts.sent],
      ['已签收', d.counts.acked],
      ['模板', (d.templates || []).length],
      ['专网', '未接'],
    ]
      .map(([a, b]) => `<span class="status-chip">${a} ${b}</span>`)
      .join('');
  }
  const box = document.getElementById('opsDocsList');
  if (!box) return;
  box.innerHTML =
    (d.items || [])
      .map((x) => {
        const btns = (x.nextLabels || [])
          .map(
            (n) =>
              `<button type="button" data-doc-st="${x.id}" data-st="${n.status}">${n.labelZh}</button>`,
          )
          .join(' ');
        const canBatch = x.status === 'draft';
        const check = canBatch
          ? `<label style="margin-right:8px"><input type="checkbox" class="ops-doc-check" data-id="${x.id}" /> 选</label>`
          : '';
        return `<div class="item" data-doc-row="${x.id}" data-status="${x.status}"><h4>${check}${x.docNo || '无文号'} · ${x.titleZh} <span class="status-chip">${x.statusZh}</span> <span class="status-chip">${x.directionZh || ''}</span></h4>
        <div class="meta">${x.counterpartyZh || ''} · ${x.id}${x.windowTitleZh ? ' · 征集窗 ' + x.windowTitleZh : ''}${x.templateNameZh ? ' · ' + x.templateNameZh : ''}</div>
        <p class="muted">${(x.bodyZh || '').slice(0, 160)}</p>
        <div class="row" style="margin-top:6px">${btns || '<span class="muted">终态</span>'}
          <button type="button" class="ghost" data-doc-win="${x.id}">改挂征集窗</button>
          <button type="button" class="ghost" data-doc-pdf="${x.id}" data-doc-no="${x.docNo || x.id}">红头 PDF</button>
          <button type="button" class="ghost" data-doc-html="${x.id}">预览套版</button>
          <button type="button" class="ghost" data-doc-ack="${x.id}">登记投递回执</button>
          <label style="margin-left:6px"><input type="checkbox" class="ops-doc-check" data-id="${x.id}" /> 选</label>
        </div></div>`;
      })
      .join('') || '<div class="muted">暂无公文。可选模板自动带文号，并可关联征集窗。</div>';
  box.querySelectorAll('[data-doc-st]').forEach((btn) => {
    btn.onclick = async () => {
      const note = prompt('备注（可留空）', '') || '';
      await api('/park/docs/' + btn.getAttribute('data-doc-st') + '/status', {
        method: 'PATCH',
        body: JSON.stringify({ status: btn.getAttribute('data-st'), noteZh: note }),
      });
      toast('公文状态已更新（未真投递）');
      refreshParkDocs();
    };
  });
  box.querySelectorAll('[data-doc-win]').forEach((btn) => {
    btn.onclick = async () => {
      const winSel = document.getElementById('opsDocWin');
      const wid = prompt('征集窗 ID（留空取消关联）', (winSel && winSel.value) || '') || '';
      await api('/park/docs/' + btn.getAttribute('data-doc-win') + '/window', {
        method: 'PATCH',
        body: JSON.stringify({ windowId: wid.trim() || null }),
      });
      toast('征集窗关联已更新');
      refreshParkDocs();
    };
  });
  box.querySelectorAll('[data-doc-pdf]').forEach((btn) => {
    btn.onclick = async () => {
      try {
        const id = btn.getAttribute('data-doc-pdf');
        const no = btn.getAttribute('data-doc-no') || id;
        const safe = String(no).replace(/[^\w\u4e00-\u9fa5.-]+/g, '_').slice(0, 40);
        const headers = {};
        const tok = localStorage.getItem('yanqi_token');
        if (tok) headers.Authorization = 'Bearer ' + tok;
        const r = await fetch('/api/park/docs/' + id + '/redhead/pdf', { headers });
        if (!r.ok) throw new Error(await r.text());
        const blob = await r.blob();
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'yanqi-park-' + safe + '.pdf';
        document.body.appendChild(a);
        a.click();
        setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
        toast('已下载红头套版 PDF（非法定公文）');
      } catch (e) {
        showErr(e);
      }
    };
  });
  box.querySelectorAll('[data-doc-html]').forEach((btn) => {
    btn.onclick = () => {
      window.open('/api/park/docs/' + btn.getAttribute('data-doc-html') + '/redhead/html', '_blank', 'noopener');
    };
  });
  box.querySelectorAll('[data-doc-ack]').forEach((btn) => {
    btn.onclick = async () => {
      const note = prompt('回执备注（可留空）', '演示投递回执') || '';
      try {
        const r = await api('/park/docs/' + btn.getAttribute('data-doc-ack') + '/delivery-ack', {
          method: 'POST',
          body: JSON.stringify({ channel: 'demo_channel', status: 'recorded', noteZh: note }),
        });
        toast(r.bannerZh || r.noteZh || '已登记投递回执');
        await refreshParkDocs();
      } catch (e) {
        showErr(e);
      }
    };
  });
  const zipBtn = document.getElementById('btnOpsRedheadZip');
  if (zipBtn && !zipBtn._bound) {
    zipBtn._bound = true;
    zipBtn.onclick = async () => {
      const ids = [...document.querySelectorAll('.ops-doc-check:checked')].map((el) => el.dataset.id).filter(Boolean);
      if (!ids.length) return toast('请先勾选公文');
      try {
        toast('正在打包红头 ZIP…');
        const headers = { 'Content-Type': 'application/json' };
        const tok = localStorage.getItem('yanqi_token');
        if (tok) headers.Authorization = 'Bearer ' + tok;
        if (state.apiKey) headers['X-API-Key'] = state.apiKey;
        const r = await fetch('/api/park/docs/redhead/zip', { method: 'POST', headers, body: JSON.stringify({ ids }) });
        if (!r.ok) {
          const text = await r.text();
          let msg = text;
          try { msg = JSON.parse(text).message || text; } catch (_) {}
          throw new Error(msg || 'ZIP 失败');
        }
        const blob = await r.blob();
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'yanqi-park-redhead-batch.zip';
        document.body.appendChild(a);
        a.click();
        setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 800);
        toast('已下载红头批量 ZIP（非法定公文）');
      } catch (e) {
        showErr(e);
      }
    };
  }
}

function selectedOpsDocIds() {
  return [...document.querySelectorAll('.ops-doc-check:checked')].map((el) => el.getAttribute('data-id')).filter(Boolean);
}
async function runOpsDocBatch(action) {
  const ids = selectedOpsDocIds();
  const msg = document.getElementById('opsDocBatchMsg');
  if (!ids.length) {
    if (msg) msg.textContent = '请先勾选草稿';
    toast('请先勾选草稿');
    return;
  }
  const templateId = document.getElementById('opsDocTpl')?.value || undefined;
  try {
    const r = await api('/park/docs/batch', {
      method: 'POST',
      body: JSON.stringify({ ids, action, templateId }),
    });
    if (msg) msg.textContent = r.bannerZh || r.noteZh || '批量完成';
    if (document.getElementById('opsDocsBanner') && r.bannerZh) {
      document.getElementById('opsDocsBanner').textContent = r.bannerZh;
    }
    toast(r.noteZh || '批量完成（未接专网）');
    await refreshParkDocs();
  } catch (e) {
    if (msg) msg.textContent = e.message || '批量失败';
    showErr(e);
  }
}
