const __rbM8 = refreshBrokers;
refreshBrokers = async function () {
  await __rbM8();
  try {
    const rows = await api('/matches?minScore=0');
    const cols = [
      ['assigned', '已分派'],
      ['contacting', '联系中'],
      ['interested', '有意向'],
      ['closed_won', '已成交'],
      ['closed_lost', '已流失'],
    ];
    const map = Object.fromEntries(cols.map(([k]) => [k, []]));
    for (const m of rows) {
      const st = m.followUpStatus || (m.brokerId ? 'assigned' : null);
      if (st && map[st]) map[st].push(m);
    }
    const kanban = document.getElementById('brokerKanban');
    if (kanban) {
      kanban.innerHTML = cols
        .map(([k, label]) => {
          const cards = (map[k] || [])
            .slice(0, 12)
            .map((m) => {
              const supply = m.capability?.title || m.outcome?.title || '-';
              return `<div class="kanban-card"><b>${(m.totalScore * 100).toFixed(0)}分</b> ${m.demand?.title || ''}<div class="meta">${supply}</div></div>`;
            })
            .join('') || '<div class="muted">空</div>';
          return `<div class="kanban-col"><h4>${label} · ${(map[k] || []).length}</h4>${cards}</div>`;
        })
        .join('');
    }
  } catch (_) {}
};

