async function openMatchDraft(matchId) {
  m9.activeMatchId = matchId;
  await openExplain(matchId);
  const m = await api('/matches/' + matchId);
  const action = (m.scoreBreakdown || {}).action;
  if (action === 'SHADOW' || action === 'HOLD') {
    if (typeof draftEditor !== 'undefined' && draftEditor) draftEditor.style.display = 'none';
    toast('这条还在内部观察，先不写对外草稿', 'warn');
    return;
  }
  let lead = (m.leads && m.leads[0]) || null;
  if (!lead) {
    lead = await api('/matches/' + matchId + '/regenerate-draft', { method: 'POST', body: '{}' });
  }
  m9.activeLeadId = lead.id;
  draftEditor.style.display = 'block';
  draftLeadMeta.textContent = `线索 ${lead.id} · 状态 ${lead.status} · 联系人 ${(lead.person && lead.person.name) || ''}`;
  draftSubject.value = lead.draftSubject || '';
  draftBody.value = lead.draftBody || '';
  draftMsg.textContent = '';
}

