document.addEventListener('keydown', (ev) => {
  const tag = (ev.target && ev.target.tagName) || '';
  if (['INPUT', 'TEXTAREA', 'SELECT'].includes(tag)) {
    if (ev.key === 'Escape') ev.target.blur();
    return;
  }
  const matchPanel = document.getElementById('tab-match');
  if (!matchPanel || !matchPanel.classList.contains('active')) return;
  if (ev.key === '/' ) {
    ev.preventDefault();
    const box = document.getElementById('globalSearchBox');
    if (box) box.focus();
    else filterScore?.focus();
    return;
  }
  if (ev.key === 'j' || ev.key === 'ArrowDown') {
    ev.preventDefault();
    m9.focusIdx = Math.min((m9.matches.length || 1) - 1, m9.focusIdx + 1);
    if (m9.focusIdx < 0) m9.focusIdx = 0;
    highlightFocus();
  } else if (ev.key === 'k' || ev.key === 'ArrowUp') {
    ev.preventDefault();
    m9.focusIdx = Math.max(0, m9.focusIdx - 1);
    highlightFocus();
  } else if (ev.key === 'e') {
    const m = m9.matches[m9.focusIdx];
    if (m) openMatchDraft(m.id);
  } else if (ev.key === 'a') {
    const m = m9.matches[m9.focusIdx];
    if (!m) return;
    api('/matches/' + m.id, { method: 'PATCH', body: JSON.stringify({ status: 'APPROVED' }) }).then(() => {
      toast('已通过');
      refreshMatches();
    });
  } else if (ev.key === 'r') {
    const m = m9.matches[m9.focusIdx];
    if (!m) return;
    api('/matches/' + m.id + '/reject-dossier', {
      method: 'POST',
      body: JSON.stringify({ reason: 'wrong_field', comment: '快捷键驳回' }),
    }).then(() => {
      toast('已按领域不对驳回', 'warn');
      refreshMatches();
    });
  }
});

