// audit export links need credentials — rewrite to fetch blob when clicked
['btnExportAuditsJson', 'btnExportAuditsCsv'].forEach((id) => {
  const a = document.getElementById(id);
  if (!a) return;
  a.onclick = async (e) => {
    e.preventDefault();
    const format = id.includes('Csv') ? 'csv' : 'json';
    const data = await api('/audits/export?format=' + format);
    const blob = new Blob([typeof data === 'string' ? data : JSON.stringify(data, null, 2)], {
      type: format === 'csv' ? 'text/csv' : 'application/json',
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = format === 'csv' ? 'yanqi-audits.csv' : 'yanqi-audits.json';
    link.click();
    URL.revokeObjectURL(url);
  };
});


/* —— M11：韧性条 / 学习权重 / 队列失败提示 —— */
async function refreshM11OpsStrip() {
  const host = document.getElementById('m11OpsStrip') || document.getElementById('slaStrip');
  if (!host) return;
  try {
    const [st, w, ready] = await Promise.all([
      api('/public/status').catch(() => null),
      api('/feedback/weights').catch(() => null),
      fetch('/api/health/ready').then((r) => r.json()).catch(() => null),
    ]);
    const q = st?.queue || {};
    const backlogBad = q.ok === false || (q.backlogAlert && q.alert);
    const box = document.getElementById('m11OpsStrip');
    if (!box) {
      const el = document.createElement('div');
      el.id = 'm11OpsStrip';
      el.className = 'item';
      el.style.margin = '8px 0';
      (document.getElementById('slaStrip')?.parentElement || document.querySelector('#view-brokers') || document.body).prepend(el);
    }
    const target = document.getElementById('m11OpsStrip');
    if (!target) return;
    target.innerHTML = `
      <div class="row" style="justify-content:space-between;gap:8px;flex-wrap:wrap">
        <div>
          <b>系统韧性</b>
          <span class="pill">${ready?.ok ? '就绪' : '未就绪'}</span>
          <span class="pill">学习 有用${w?.usefulN ?? 0}/不准${w?.notUsefulN ?? 0}</span>
          ${backlogBad ? '<span class="badge-danger">队列积压告警</span>' : '<span class="pill">队列正常</span>'}
        </div>
        <div class="muted" style="font-size:12px">限流剩余见响应头 X-RateLimit-Remaining · 关键 POST 可带 Idempotency-Key</div>
      </div>
      ${backlogBad ? `<div class="live-warn" style="margin-top:6px">队列有积压或失败任务，先看「任务日志」再批量重跑，避免重复写。</div>` : ''}
    `;
  } catch (e) {
    console.warn('m11 strip', e);
  }
}
