/* —— M12：告警徽章 + 匹配评测 —— */
async function refreshM12Alerts() {
  try {
    const [al, ev] = await Promise.all([
      api('/metrics/alerts/evaluate', { method: 'POST', body: '{}' }).catch(() => api('/metrics/alerts')),
      api('/metrics/match-eval').catch(() => null),
    ]);
    let badge = document.getElementById('opsAlertBadge');
    if (!badge) {
      badge = document.createElement('span');
      badge.id = 'opsAlertBadge';
      badge.className = 'ops-alert-badge';
      const host =
        document.querySelector('header .brand') ||
        document.querySelector('nav') ||
        document.getElementById('m11OpsStrip') ||
        document.body;
      host.appendChild(badge);
    }
    const n = al?.activeCount || 0;
    const crit = al?.criticalCount || 0;
    badge.className = 'ops-alert-badge' + (crit ? ' critical' : '');
    const evalOk = ev?.latest?.ok;
    badge.textContent =
      (n ? `告警 ${n}${crit ? '·急' : ''}` : '告警清') +
      (evalOk === false ? ' · 评测红' : evalOk ? ' · 评测绿' : '');
    badge.title = (al?.alerts || [])
      .filter((a) => !a.acked)
      .map((a) => a.message)
      .slice(0, 5)
      .join('\n') || '无活跃告警';

    const strip = document.getElementById('m11OpsStrip');
    if (strip && ev?.latest) {
      let slot = document.getElementById('m12EvalSlot');
      if (!slot) {
        slot = document.createElement('div');
        slot.id = 'm12EvalSlot';
        slot.className = 'meta';
        slot.style.marginTop = '6px';
        strip.appendChild(slot);
      }
      slot.textContent = `匹配评测：${ev.latest.ok ? '通过' : '未通过'} ${ev.latest.passed || 0}/${ev.latest.total || 0} · ${ev.latest.evaluatedAt || ''}`;
    }
  } catch (e) {
    console.warn('m12 alerts', e);
  }
}
setTimeout(() => refreshM12Alerts().catch(() => {}), 1200);

async function refreshHomeCacheShellDash() {
  const el = document.getElementById('homeCacheShellDash');
  if (!el) return;
  try {
    const hc = await api('/metrics/home-cache');
    const shells = hc.byShell || {};
    const keys = Object.keys(shells);
    const alert = hc.alert || {};
    let html =
      '<div class="meta" style="margin-bottom:8px">合计命中率 <strong>' +
      (hc.hitRatePct == null ? '—' : hc.hitRatePct + '%') +
      '</strong> · HIT ' +
      (hc.hits || 0) +
      ' / MISS ' +
      (hc.misses || 0) +
      ' / BYPASS ' +
      (hc.bypass || 0) +
      (alert.alerting ? ' · <span style="color:#9a3412">告警中</span>' : '') +
      '</div>';
    if (!keys.length) {
      html += '<p class="muted" style="margin:0">还没有分壳样本。各壳登录后打开工作台首页即可积累。</p>';
    } else {
      html +=
        '<table class="plain" style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr>' +
        '<th style="text-align:left;padding:4px 6px">壳</th><th>HIT</th><th>MISS</th><th>BYPASS</th><th>命中率</th><th>样本</th></tr></thead><tbody>';
      for (const k of keys) {
        const s = shells[k] || {};
        html +=
          '<tr><td style="padding:4px 6px"><code>' +
          k +
          '</code></td><td style="text-align:center">' +
          (s.hits || 0) +
          '</td><td style="text-align:center">' +
          (s.misses || 0) +
          '</td><td style="text-align:center">' +
          (s.bypass || 0) +
          '</td><td style="text-align:center">' +
          (s.hitRatePct == null ? '—' : s.hitRatePct + '%') +
          '</td><td style="text-align:center">' +
          (s.samples || 0) +
          '</td></tr>';
      }
      html += '</tbody></table>';
    }
    el.innerHTML = html;
    try { refreshInboxDeltaCacheDash(); } catch (_) {}
  } catch (e) {
    el.textContent = '分壳命中加载失败：' + (e.message || e);
  }
}

async function refreshInboxDeltaCacheDash() {
  const el = document.getElementById('inboxDeltaCacheDash');
  const badge = document.getElementById('inboxDeltaCacheBadge');
  if (!el && !badge) return;
  try {
    const [hc, alerts] = await Promise.all([
      api('/metrics/inbox-delta-cache'),
      api('/metrics/inbox-delta-cache/curve/alerts').catch(() => null),
    ]);
    const pct = hc.hitRatePct != null ? hc.hitRatePct + '%' : '—';
    const alerting = !!(alerts && alerts.alerting) || !!(hc.alert && hc.alert.alerting);
    if (badge) {
      badge.textContent = (alerting ? '收件箱偏低 ' : '收件箱命中 ') + pct;
      badge.style.background = alerting ? '#fff7ed' : '';
      badge.style.borderColor = alerting ? '#fdba74' : '';
      const heal0 =
        (alerts && alerts.selfHealHintsZh && alerts.selfHealHintsZh[0]) ||
        (alerting ? '可定向 bust 偏低壳后少用 ?fresh=1' : '');
      badge.title =
        (alerting ? (alerts && alerts.messageZh) || (hc.alert && hc.alert.messageZh) || '持续偏低' : '正常') +
        (heal0 ? ' · 自愈：' + heal0 : '') +
        ' · HIT ' +
        (hc.hits || 0) +
        ' · MISS ' +
        (hc.misses || 0) +
        ' · 304 ' +
        (hc.notModified || 0) +
        ' · 壳 ' +
        (hc.shellCount || 0);
      if (alerting) { badge.classList.add('m64-inbox-selfheal'); badge.classList.add('m65-inbox-selfheal-bust'); badge.classList.add('m66-inbox-hit-probe'); }
      else { badge.classList.remove('m64-inbox-selfheal'); badge.classList.remove('m65-inbox-selfheal-bust'); badge.classList.remove('m66-inbox-hit-probe'); }
    }
    if (el) {
      const shells = hc.byShell || {};
      let text =
        '收件箱 delta 分壳命中（M65）\n合计命中率 ' +
        pct +
        ' · HIT ' +
        (hc.hits || 0) +
        ' · MISS ' +
        (hc.misses || 0) +
        ' · 304 ' +
        (hc.notModified || 0) +
        '\n';
      if (alerts && alerts.messageZh) {
        text += (alerts.alerting ? '⚠ ' : '✓ ') + alerts.messageZh + '\n';
      }
      const keys = Object.keys(shells).sort();
      for (const k of keys) {
        const r = shells[k];
        const shellAlert = ((alerts && alerts.shells) || []).find((x) => x.shell === k);
        const mark = shellAlert && shellAlert.alerting ? ' ⚠' : '';
        text +=
          k +
          ': HIT ' +
          r.hits +
          ' MISS ' +
          r.misses +
          ' 命中 ' +
          (r.hitRatePct != null ? r.hitRatePct + '%' : '—') +
          mark +
          '\n';
      }
      if (alerts && alerts.selfHealHintsZh && alerts.selfHealHintsZh.length) {
        text += '\n【自愈提示】\n' + alerts.selfHealHintsZh.map((h, i) => i + 1 + '. ' + h).join('\n') + '\n';
      }
      if (alerts && alerts.dualChannel) {
        text +=
          '\n双通道：' +
          (alerts.dualChannel.channel1Zh || '通道一') +
          ' · ' +
          (alerts.dualChannel.channel2Zh || '通道二') +
          '（干跑）';
      }
      el.textContent = text.trim() || '暂无样本';
    }
  } catch (e) {
    if (el) el.textContent = '收件箱命中加载失败：' + (e.message || e);
    if (badge) badge.textContent = '收件箱命中 —';
  }
}

