function paintBustThrottleCountdown(r) {
  const el = document.getElementById('bustThrottleCountdown');
  if (!el) return;
  if (window.__yanqiThrottleCountdownTimer) {
    clearInterval(window.__yanqiThrottleCountdownTimer);
    window.__yanqiThrottleCountdownTimer = null;
  }
  let sec = Number(r && r.countdownSec) || 0;
  if (!(r && r.throttled) || sec <= 0) {
    el.textContent = (r && r.countdownLabelZh) || (sec <= 0 ? '冷却结束，可执行' : '');
    return;
  }
  const tick = async () => {
    el.textContent = '冷却倒计时 ' + sec + 's';
    if (sec <= 0) {
      el.textContent = '冷却结束，可执行';
      if (window.__yanqiThrottleCountdownTimer) {
        clearInterval(window.__yanqiThrottleCountdownTimer);
        window.__yanqiThrottleCountdownTimer = null;
      }
      // M78：倒计时归零可选自动复探针（干跑通知）
      const chk = document.getElementById('chkAutoReprobeOnCountdown');
      const autoOn = !chk || chk.checked;
      if (autoOn && !window.__yanqiCountdownAutoReprobeLock) {
        window.__yanqiCountdownAutoReprobeLock = true;
        try {
          const ar = await api(
            '/metrics/inbox-delta-cache/curve/alerts/suggested-bust/countdown-end-auto-reprobe',
            { method: 'POST', body: JSON.stringify({ notifyDryRun: true }) },
          );
          if (typeof YB !== 'undefined' && YB.toast)
            YB.toast(ar.toastZh || '倒计时结束 · 自动复探针（干跑）', 'ok', 2600);
        } catch (e) {
          if (typeof YB !== 'undefined' && YB.toast)
            YB.toast((e && e.message) || '自动复探针失败', 'warn', 2200);
        } finally {
          setTimeout(() => {
            window.__yanqiCountdownAutoReprobeLock = false;
          }, 4000);
        }
      }
      return;
    }
    sec -= 1;
  };
  tick();
  window.__yanqiThrottleCountdownTimer = setInterval(tick, 1000);
}

