document.getElementById('btnAnomalyChainEventSource') &&
  (document.getElementById('btnAnomalyChainEventSource').onclick = async () => {
    const btn = document.getElementById('btnAnomalyChainEventSource');
    if (btn) btn.disabled = true;
    let es = null;
    try {
      if (typeof YB !== 'undefined' && YB.busy) YB.busy(true, '订阅异常串联真 EventSource…');
      const streamPath =
        '/api/metrics/inbox-delta-cache/curve/alerts/shell-health/weekly-sparkline/day-drill/trend-anomaly/chain-bust-reprobe/stream';
      if (typeof EventSource === 'undefined') {
        showDlg('当前环境无 EventSource，请用「查看异常串联分项进度」轮询。');
        return;
      }
      window.__yanqiAnomalyLastEventId = window.__yanqiAnomalyLastEventId || null;
      const __sseBase = await sseUrl(streamPath);
      const __reconnectQs = window.__yanqiAnomalyLastEventId
        ? (__sseBase.indexOf('?') >= 0 ? '&' : '?') +
          'lastEventId=' +
          encodeURIComponent(window.__yanqiAnomalyLastEventId)
        : '';
      const __sse = __sseBase + __reconnectQs;
      es = new EventSource(__sse);
      const lines = [];
      await new Promise((resolve, reject) => {
        const t = setTimeout(() => {
          try { es.close(); } catch (_) {}
          resolve();
        }, 4500);
        es.addEventListener('progress', (ev) => {
          try {
            const data = JSON.parse(ev.data || '{}');
            if (data.eventId != null) window.__yanqiAnomalyLastEventId = data.eventId;
            else if (data.lastEventId != null) window.__yanqiAnomalyLastEventId = data.lastEventId;
            const phases = data.itemizedPhases || [];
            const contrast = data.itemizedContrast;
            if (contrast && contrast.summaryZh) {
              lines.push('对照·' + contrast.summaryZh);
            }
            const pl = phases
              .map(function (p) {
                return (p.labelZh || p.id) + '·' + (p.statusZh || p.status);
              })
              .join(' / ');
            lines.push(
              'percent=' +
                (data.percent != null ? data.percent : '—') +
                ' phase=' +
                (data.phase || '—') +
                (pl ? ' · ' + pl : ''),
            );
            const dash = document.getElementById('inboxDeltaCacheDash');
            if (dash)
              dash.textContent =
                '【异常串联 EventSource·可续订】\n' + lines.slice(-8).join('\n') + '\n' + (data.tipZh || '') + (window.__yanqiAnomalyLastEventId ? '\nlastEventId=' + window.__yanqiAnomalyLastEventId : '');
            if (!data.waiting) {
              clearTimeout(t);
              try { es.close(); } catch (_) {}
              resolve();
            }
          } catch (e) {
            clearTimeout(t);
            reject(e);
          }
        });
        es.addEventListener('end', () => {
          clearTimeout(t);
          try { es.close(); } catch (_) {}
          resolve();
        });
        es.onerror = () => {
          clearTimeout(t);
          try { es.close(); } catch (_) {}
          resolve();
        };
      });
      if (typeof YB !== 'undefined' && YB.toast)
        YB.toast(lines.length ? 'EventSource 分项已推送' : 'EventSource 已连接（暂无进行中任务）', 'ok', 2400);
      showDlg('异常串联真 EventSource\n' + (lines.length ? lines.join('\n') : '无进行中任务卡；可先一键串联再订阅。'));
    } catch (e) {
      if (typeof YB !== 'undefined' && YB.toast) YB.toast(e.message || 'EventSource 失败', 'err');
    } finally {
      try { if (es) es.close(); } catch (_) {}
      if (typeof YB !== 'undefined' && YB.busy) YB.busy(false);
      if (btn) btn.disabled = false;
    }
  });

